package eu.nitok.jitsu.gradle

import org.assertj.core.api.Assertions.assertThat
import java.io.File
import org.gradle.testkit.runner.GradleRunner
import org.gradle.testkit.runner.TaskOutcome
import org.junit.jupiter.api.Test
import org.junit.jupiter.api.io.TempDir

/**
 * A simple functional test for the 'org.example.greeting' plugin.
 */
class JitsuPluginFunctionalTest {

    @field:TempDir
    lateinit var projectDir: File

    private val buildFile by lazy { projectDir.resolve("build.gradle") }
    private val settingsFile by lazy { projectDir.resolve("settings.gradle") }

    private fun writeFile(path: String, content: String) {
        val file = projectDir.resolve(path)
        file.parentFile.mkdirs()
        file.writeText(content)
    }

    @Test fun `can run task`() {
        // Set up the test build
        settingsFile.writeText("")
        buildFile.writeText("""
            plugins {
                id('eu.nitok.jitsu-lib')
            }
        """.trimIndent())

        // Run the build
        val runner = GradleRunner.create()
        runner.forwardOutput()
        runner.withPluginClasspath()
        runner.withArguments("compileTestJitsu")
        runner.withProjectDir(projectDir)
        runner.build()
    }

    @Test fun `jitsu consumers resolve bindings while plain native consumers resolve main library`() {
        settingsFile.writeText(
            """
            rootProject.name = 'test-root'
            include('producer', 'jitsuConsumer', 'nativeConsumer')
            """.trimIndent()
        )

        writeFile(
            "producer/build.gradle",
            """
            plugins {
                id('eu.nitok.jitsu-lib')
            }

            group = 'eu.nitok.test'
            version = '1.0'
            """.trimIndent()
        )
        writeFile("producer/src/main/jitsu/main.jit", "fn main(): i16 { return 0; }")
        writeFile("producer/src/main/c/bindings.c", "int producer_binding() { return 1; }")

        writeFile(
            "jitsuConsumer/build.gradle",
            """
            plugins {
                id('eu.nitok.jitsu-lib')
            }

            group = 'eu.nitok.test'
            version = '1.0'

            dependencies {
                jitsuMain project(':producer')
            }

            def debugConfig = configurations.create('resolveDebugBindings') {
                canBeConsumed = false
                canBeResolved = true
                attributes {
                    attribute(org.gradle.api.attributes.Usage.USAGE_ATTRIBUTE, objects.named(org.gradle.api.attributes.Usage, org.gradle.api.attributes.Usage.NATIVE_LINK))
                    attribute(org.gradle.language.cpp.CppBinary.DEBUGGABLE_ATTRIBUTE, true)
                    attribute(org.gradle.language.cpp.CppBinary.OPTIMIZED_ATTRIBUTE, false)
                    attribute(org.gradle.language.cpp.CppBinary.LINKAGE_ATTRIBUTE, org.gradle.nativeplatform.Linkage.STATIC)
                    attribute(org.gradle.nativeplatform.OperatingSystemFamily.OPERATING_SYSTEM_ATTRIBUTE, objects.named(org.gradle.nativeplatform.OperatingSystemFamily, org.gradle.nativeplatform.platform.internal.DefaultNativePlatform.host().operatingSystem.toFamilyName()))
                    attribute(org.gradle.nativeplatform.MachineArchitecture.ARCHITECTURE_ATTRIBUTE, objects.named(org.gradle.nativeplatform.MachineArchitecture, org.gradle.nativeplatform.platform.internal.DefaultNativePlatform.host().architecture.name))
                }
            }

            dependencies {
                add('resolveDebugBindings', project(':producer')) {
                    capabilities { requireFeature('bindings') }
                }
            }

            tasks.register('printBindingsArtifact') {
                doLast {
                    println('BINDINGS_ARTIFACT=' + configurations.resolveDebugBindings.singleFile.name)
                }
            }
            """.trimIndent()
        )
        writeFile("jitsuConsumer/src/main/jitsu/main.jit", "fn main():i16 { return 0; }")

        writeFile(
            "nativeConsumer/build.gradle",
            """
            plugins {
                id('cpp-library')
            }

            library {
                linkage = [org.gradle.nativeplatform.Linkage.SHARED]
                dependencies {
                    implementation project(':producer')
                }
            }

            def debugConfig = configurations.create('resolveDebugMain') {
                canBeConsumed = false
                canBeResolved = true
                attributes {
                    attribute(org.gradle.api.attributes.Usage.USAGE_ATTRIBUTE, objects.named(org.gradle.api.attributes.Usage, org.gradle.api.attributes.Usage.NATIVE_LINK))
                    attribute(org.gradle.language.cpp.CppBinary.DEBUGGABLE_ATTRIBUTE, true)
                    attribute(org.gradle.language.cpp.CppBinary.OPTIMIZED_ATTRIBUTE, false)
                    attribute(org.gradle.language.cpp.CppBinary.LINKAGE_ATTRIBUTE, org.gradle.nativeplatform.Linkage.SHARED)
                    attribute(org.gradle.nativeplatform.OperatingSystemFamily.OPERATING_SYSTEM_ATTRIBUTE, objects.named(org.gradle.nativeplatform.OperatingSystemFamily, org.gradle.nativeplatform.platform.internal.DefaultNativePlatform.host().operatingSystem.toFamilyName()))
                    attribute(org.gradle.nativeplatform.MachineArchitecture.ARCHITECTURE_ATTRIBUTE, objects.named(org.gradle.nativeplatform.MachineArchitecture, org.gradle.nativeplatform.platform.internal.DefaultNativePlatform.host().architecture.name))
                }
            }

            dependencies {
                add('resolveDebugMain', project(':producer'))
            }

            tasks.register('printMainArtifact') {
                doLast {
                    println('MAIN_ARTIFACT=' + configurations.resolveDebugMain.singleFile.name)
                }
            }
            """.trimIndent()
        )

        val result = GradleRunner.create()
            .forwardOutput()
            .withPluginClasspath()
            .withArguments(":jitsuConsumer:printBindingsArtifact", ":nativeConsumer:printMainArtifact")
            .withProjectDir(projectDir)
            .build()

        assertThat(result.task(":jitsuConsumer:printBindingsArtifact")?.outcome).isEqualTo(TaskOutcome.SUCCESS)
        assertThat(result.task(":nativeConsumer:printMainArtifact")?.outcome).isEqualTo(TaskOutcome.SUCCESS)
        assertThat(result.output).contains("BINDINGS_ARTIFACT=libproducer.a")
        assertThat(result.output).contains("MAIN_ARTIFACT=libproducer.so")
    }

    @Test fun `jitsuMain dependency wires the producer bindings into the consumers native compilation`() {
        settingsFile.writeText(
            """
            rootProject.name = 'test-root'
            include('producer', 'consumer')
            """.trimIndent()
        )

        writeFile(
            "producer/build.gradle",
            """
            plugins {
                id('eu.nitok.jitsu-lib')
            }

            group = 'eu.nitok.test'
            version = '1.0'
            """.trimIndent()
        )
        writeFile(
            "producer/src/main/jitsu/main.jit",
            """
            import jitsu;

            fn main():i16 {
                return 1;
            }
            """.trimIndent()
        )
        writeFile("producer/src/main/c/bindings.c", "int producer_binding() { return 1; }")

        writeFile(
            "consumer/build.gradle",
            """
            plugins {
                id('eu.nitok.jitsu-app')
            }

            group = 'eu.nitok.test'
            version = '1.0'

            dependencies {
                jitsuMain project(':producer')
            }

            tasks.register('printResolution') {
                def link = configurations.nativeLinkDebug
                def ir = configurations.mainJitsuModuleClasspath
                doLast {
                    link.files.each { println('LINK=' + it.name) }
                    ir.files.each { println('IR=' + it.name) }
                }
            }
            """.trimIndent()
        )
        writeFile(
            "consumer/src/main/jitsu/main.jit",
            """
            import jitsu;

            fn main():i16 {
                return 2;
            }
            """.trimIndent()
        )

        val result = GradleRunner.create()
            .forwardOutput()
            .withPluginClasspath()
            .withArguments(":consumer:printResolution")
            .withProjectDir(projectDir)
            .build()

        assertThat(result.task(":consumer:printResolution")?.outcome).isEqualTo(TaskOutcome.SUCCESS)
        // the consumer re-generates the producer's C from its IR, so it must link the producer's
        // hand written bindings only - never the producer's compiled generated code
        assertThat(result.output).contains("LINK=libproducer.a")
        assertThat(result.output).doesNotContain("LINK=libproducer.so")
        assertThat(result.output).contains("IR=producer.jim")
    }

    @Test fun `bindings of transitive jitsu modules reach the consumer`() {
        settingsFile.writeText(
            """
            rootProject.name = 'test-root'
            include('base', 'mid', 'app')
            """.trimIndent()
        )

        // base has hand written C, mid deliberately has none: a module without src/main/c must
        // still produce a linkable bindings archive, otherwise consumers fail with
        // "cannot find libmid.a"
        listOf("base", "mid").forEach { name ->
            writeFile(
                "$name/build.gradle",
                """
                plugins {
                    id('eu.nitok.jitsu-lib')
                }

                group = 'eu.nitok.test'
                version = '1.0'
                ${if (name == "mid") "dependencies { jitsuMain project(':base') }" else ""}
                """.trimIndent()
            )
            writeFile("$name/src/main/jitsu/main.jit", "fn ${name}Fn():i16 { return 1; }")
        }
        writeFile("base/src/main/c/base.c", "int base_binding() { return 1; }")

        writeFile(
            "app/build.gradle",
            """
            plugins {
                id('eu.nitok.jitsu-app')
            }

            group = 'eu.nitok.test'
            version = '1.0'

            dependencies {
                jitsuMain project(':mid')
            }

            tasks.register('printResolution') {
                def link = configurations.nativeLinkDebug
                doLast { link.files.each { println('LINK=' + it.name) } }
            }
            """.trimIndent()
        )
        writeFile("app/src/main/jitsu/main.jit", "fn main():i16 { return 0; }")

        val result = GradleRunner.create()
            .forwardOutput()
            .withPluginClasspath()
            .withArguments(":app:printResolution")
            .withProjectDir(projectDir)
            .build()

        // app only declares ':mid', but its generated C inlines base's code too
        assertThat(result.output).contains("LINK=libmid.a")
        assertThat(result.output).contains("LINK=libbase.a")
    }
}
